-- Phase 6 migration
CREATE TABLE IF NOT EXISTS suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,email TEXT,address TEXT,trn TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS purchase_orders(id INTEGER PRIMARY KEY AUTOINCREMENT,number TEXT UNIQUE NOT NULL,supplier_id INTEGER,project_id INTEGER,status TEXT DEFAULT 'Draft',order_date TEXT,expected_date TEXT,subtotal REAL DEFAULT 0,vat_rate REAL DEFAULT 5,vat REAL DEFAULT 0,total REAL DEFAULT 0,notes TEXT);
CREATE TABLE IF NOT EXISTS purchase_order_items(id INTEGER PRIMARY KEY AUTOINCREMENT,purchase_order_id INTEGER NOT NULL,item_id INTEGER,description TEXT NOT NULL,qty REAL DEFAULT 1,unit TEXT DEFAULT 'PCS',rate REAL DEFAULT 0,amount REAL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory_items(id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT UNIQUE,name TEXT NOT NULL,category TEXT,unit TEXT DEFAULT 'PCS',quantity REAL DEFAULT 0,min_quantity REAL DEFAULT 0,average_cost REAL DEFAULT 0,location TEXT);
CREATE TABLE IF NOT EXISTS inventory_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,item_id INTEGER NOT NULL,type TEXT NOT NULL,qty REAL NOT NULL,unit_cost REAL DEFAULT 0,total_cost REAL DEFAULT 0,date TEXT,reference TEXT,project_id INTEGER,purchase_order_id INTEGER,notes TEXT);
CREATE TABLE IF NOT EXISTS project_materials(id INTEGER PRIMARY KEY AUTOINCREMENT,project_id INTEGER NOT NULL,item_id INTEGER NOT NULL,qty REAL NOT NULL,unit_cost REAL DEFAULT 0,total_cost REAL DEFAULT 0,date TEXT,reference TEXT);